    val n = st.nextToken().toLong()
    val m = st.nextToken().toLong()
    val k = st.nextToken().toLong()
    val mod = 998244353L

    fun nCr(nVal: Long, kVal: Long): Long {
        var kLocal = kVal
        if (kLocal > nVal - kLocal) {
            kLocal = nVal - kLocal
        }
        var res = 1L
        var i = 0L
        while (i < kLocal) {
            res = res * (nVal - i) / (i + 1)
            i++
        }
        return res
    }

    val selection = nCr(n - 1, k) % mod

    fun modPow(base: Long, exp: Long, modVal: Long): Long {
        var b = base % modVal
        var e = exp
        var result = 1L
        while (e > 0) {
            if ((e and 1L) == 1L) {
                result = (result * b) % modVal
            }
            b = (b * b) % modVal
            e = e shr 1
        }
        return result
    }

    val colorsWays = (m % mod) * modPow((m - 1 + mod) % mod, k, mod) % mod
    val totalWays = colorsWays * selection % mod
